diff --git a/backend/internal/workspace/manifest.go b/backend/internal/workspace/manifest.go
--- a/backend/internal/workspace/manifest.go
+++ b/backend/internal/workspace/manifest.go
@@ -12,6 +12,14 @@ package workspace
+// loadManifest reads the workspace manifest from disk.
+func loadManifest(path string) (Manifest, error) {
+	raw, err := os.ReadFile(path)
+	if err != nil {
+		return Manifest{}, err
+	}
+	var m Manifest
+	return m, json.Unmarshal(raw, &m)
+}
